1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { DEDICATED_IP_PRICE_CENTS } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { maybeRewardReferral } from "./actions-growth";
12	
13	export class OrderError extends Error {}
14	
15	export const orderSchema = z.object({
16	  planId: z.string().min(1),
17	  osTemplateId: z.string().min(1),
18	  hostname: z
19	    .string()
20	    .min(3)
21	    .max(40)
22	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
23	});
24	
25	export type OrderIntent = {
26	  planId: string;
27	  osTemplateId: string;
28	  hostname: string;
29	  nodeId?: string;
30	  addonMalware?: boolean;
31	  addonBackup?: boolean;
32	  addonDocker?: boolean;
33	  termMonths?: number;
34	  dedicatedIp?: boolean;
35	  sshPublicKey?: string;
36	  sshKeyName?: string;
37	  free?: boolean;
38	};
39	
40	/** Extract a plain OrderIntent from a deploy form. */
41	export function intentFromFormData(formData: FormData): OrderIntent {
42	  return {
43	    planId: String(formData.get("planId") ?? ""),
44	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
45	    hostname: String(formData.get("hostname") ?? ""),
46	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
47	    addonMalware: formData.get("addon_malware") === "1",
48	    addonBackup: formData.get("addon_backup") === "1",
49	    addonDocker: formData.get("addon_docker") === "1",
50	    termMonths: Number(formData.get("termMonths") ?? 1),
51	    dedicatedIp: formData.get("dedicatedIp") === "1",
52	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
53	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
54	    free: formData.get("free") === "1",
55	  };
56	}
57	
58	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
59	async function scheduleNode(planRamMB: number) {
60	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
61	  if (nodes.length === 0) return null;
62	  const loads = await Promise.all(
63	    nodes.map(async (n) => {
64	      const agg = await db.server.findMany({
65	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
66	        select: { plan: { select: { ramMB: true } } },
67	      });
68	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
69	      return { node: n, free: n.capacityRamMB - used };
70	    }),
71	  );
72	  loads.sort((a, b) => b.free - a.free);
73	  return loads[0].node;
74	}
75	
76	/** Validate + price an order without placing it. Throws OrderError on any problem. */
77	export async function orderQuote(intent: OrderIntent) {
78	  const parsed = orderSchema.safeParse(intent);
79	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
80	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
81	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
82	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
83	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
84	    throw new OrderError(
85	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
86	    );
87	  }
88	  const term = vpsTerm(Number(intent.termMonths ?? 1));
89	  const ipCents = intent.dedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0;
90	  const chargeCents = vpsTermPriceCents(plan.priceCents, term.months) + ipCents;
91	  return { plan, os, term, chargeCents };
92	}
93	
94	/**
95	 * Place an order: validate, charge the wallet (unless a free admin grant),
96	 * create the Server + PROVISION job. Returns the new server id. Does NOT
97	 * redirect. Callers must ensure funds exist (or pass free) — this still
98	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
99	 */
100	export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
101	  const { plan, os, term, chargeCents } = await orderQuote(intent);
102	
103	  const cap = await capacityCheck(plan.id);
104	  if (!cap.ok) throw new OrderError(cap.reason);
105	
106	  let nodeId: string | null = null;
107	  if (intent.nodeId) {
108	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
109	    if (!n) throw new OrderError("Selected location is not available.");
110	    nodeId = n.id;
111	  } else {
112	    const n = await scheduleNode(plan.ramMB);
113	    nodeId = n?.id ?? null;
114	  }
115	
116	  const diskCap = await diskCapacityCheck(nodeId, plan.diskGB);
117	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
118	
119	  const addons = {
120	    malwareScanner: !!intent.addonMalware,
121	    dailyBackup: !!intent.addonBackup,
122	    docker: !!intent.addonDocker,
123	  };
124	  const isAdmin = user.role === "ADMIN";
125	  const freeRequested = !!intent.free && isAdmin;
126	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
127	
128	  const newKey = (intent.sshPublicKey ?? "").trim();
129	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
130	
131	  let server;
132	  try {
133	    server = await db.$transaction(async (tx) => {
134	      if (!freeRequested) {
135	        await debitWallet(tx, user.id, chargeCents);
136	        await tx.walletTransaction.create({
137	          data: {
138	            userId: user.id,
139	            amountCents: -chargeCents,
140	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}`,
141	          },
142	        });
143	      }
144	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
145	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
146	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
147	      }
148	      const s = await tx.server.create({
149	        data: {
150	          name: intent.hostname,
151	          hostname: intent.hostname,
152	          userId: user.id,
153	          planId: plan.id,
154	          osTemplateId: os.id,
155	          nodeId,
156	          addons,
157	          termMonths: term.months,
158	          wantsDedicatedIp: !!intent.dedicatedIp,
159	          isFree: freeRequested,
160	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
161	        },
162	      });
163	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
164	      return s;
165	    });
166	  } catch (e) {
167	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
168	    throw e;
169	  }
170	
171	  await db.auditLog.create({
172	    data: {
173	      userId: user.id,
174	      action: "server.order",
175	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`,
176	    },
177	  });
178	  if (!freeRequested) {
179	    try {
180	      await maybeRewardReferral(user.id);
181	    } catch {
182	      /* non-fatal */
183	    }
184	  }
185	  return server.id;
186	}
