1	import Stripe from "stripe";
2	import { db } from "./db";
3	import type { OrderIntent } from "./order";
4	
5	export function stripeConfigured(): boolean {
6	  return !!process.env.STRIPE_SECRET_KEY;
7	}
8	
9	let client: Stripe | null = null;
10	
11	export function stripe(): Stripe {
12	  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
13	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
14	  return client;
15	}
16	
17	/** Create a Checkout session that pays for a VPS order directly (no wallet pre-fund). */
18	export async function createOrderCheckout(
19	  user: { id: string; email: string },
20	  amountCents: number,
21	  intent: OrderIntent,
22	): Promise<string | null> {
23	  if (!stripeConfigured() || amountCents <= 0) return null;
24	  const base = process.env.APP_URL ?? "http://localhost:3000";
25	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
26	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
27	  const session = await stripe().checkout.sessions.create({
28	    mode: "payment",
29	    customer_email: user.email,
30	    line_items: [
31	      {
32	        price_data: {
33	          currency: "usd",
34	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
35	          unit_amount: amountCents,
36	        },
37	        quantity: 1,
38	      },
39	    ],
40	    metadata: { nxeonUserId: user.id, nxeonOrder: JSON.stringify(slim).slice(0, 490) },
41	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
42	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
43	  });
44	  return session.url;
45	}
46	
47	/** For the confirm route: the order intent attached to a paid session, if any. */
48	export async function getCheckoutOrderIntent(
49	  sessionId: string,
50	): Promise<{ userId: string; intent: OrderIntent } | null> {
51	  if (!stripeConfigured()) return null;
52	  try {
53	    const session = await stripe().checkout.sessions.retrieve(sessionId);
54	    const userId = session.metadata?.nxeonUserId;
55	    const raw = session.metadata?.nxeonOrder;
56	    if (!userId || !raw || session.payment_status !== "paid") return null;
57	    return { userId, intent: JSON.parse(raw) as OrderIntent };
58	  } catch {
59	    return null;
60	  }
61	}
62	
63	/**
64	 * Credit a user's wallet for a completed Checkout session, idempotently.
65	 * Called from both the success-redirect confirm route (works without HTTPS)
66	 * and the webhook (belt-and-suspenders once HTTPS is available).
67	 * Returns true if a credit was applied this call.
68	 */
69	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
70	  const session = await stripe().checkout.sessions.retrieve(sessionId);
71	  const userId = session.metadata?.nxeonUserId;
72	  const cents = session.amount_total ?? 0;
73	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
74	
75	  const existing = await db.walletTransaction.findFirst({
76	    where: { description: { contains: session.id } },
77	  });
78	  if (existing) return false;
79	
80	  await db.$transaction([
81	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
82	    db.walletTransaction.create({
83	      data: { userId, amountCents: cents, description: `Stripe payment (${session.id})` },
84	    }),
85	    db.notification.create({
86	      data: {
87	        userId,
88	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
89	        href: "/dashboard/billing",
90	      },
91	    }),
92	  ]);
93	  // A funded wallet is the referred user's first paid action — reward both sides.
94	  try {
95	    const { maybeRewardReferral } = await import("./actions-growth");
96	    await maybeRewardReferral(userId);
97	  } catch { /* best-effort */ }
98	  try {
99	    const u = await db.user.findUnique({ where: { id: userId } });
100	    if (u) {
101	      const { sendMail, emails } = await import("./mailer");
102	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
103	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
104	    }
105	  } catch { /* best-effort */ }
106	  return true;
107	}
