     1	import { NextRequest, NextResponse } from "next/server";
     2	import { currentUser } from "@/lib/auth";
     3	import { stripe, stripeConfigured } from "@/lib/stripe";
     4	
     5	export async function POST(req: NextRequest) {
     6	  const user = await currentUser();
     7	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
     8	  if (!stripeConfigured()) {
     9	    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
    10	  }
    11	  const { amount } = await req.json().catch(() => ({}));
    12	  const dollars = Number(amount);
    13	  if (!Number.isFinite(dollars) || dollars < 5 || dollars > 5000) {
    14	    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
    15	  }
    16	  const base = process.env.APP_URL ?? "http://localhost:3000";
    17	  const session = await stripe().checkout.sessions.create({
    18	    mode: "payment",
    19	    customer_email: user.email,
    20	    line_items: [
    21	      {
    22	        price_data: {
    23	          currency: "usd",
    24	          product_data: { name: "Nxeon wallet credit" },
    25	          unit_amount: Math.round(dollars * 100),
    26	        },
    27	        quantity: 1,
    28	      },
    29	    ],
    30	    metadata: { nxeonUserId: user.id },
    31	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    32	    cancel_url: `${base}/dashboard/billing?canceled=1`,
    33	  });
    34	  return NextResponse.json({ url: session.url });
    35	}

