26	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
27	async function uniqueReferralCode(): Promise<string> {
28	  for (let i = 0; i < 6; i++) {
29	    const code = generateReferralCode();
30	    const clash = await db.user.findUnique({ where: { referralCode: code } });
31	    if (!clash) return code;
32	  }
33	  // Extremely unlikely; fall back to a longer code.
34	  return generateReferralCode(12);
35	}
