48	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
49	  const parsed = credsSchema
50	    .extend({
51	      name: z.string().min(1).max(100),
52	      password: z
53	        .string()
54	        .min(8, "Password must be at least 8 characters")
55	        .max(200)
56	        .regex(/[a-zA-Z]/, "Password must include a letter")
57	        .regex(/[0-9]/, "Password must include a number"),
58	    })
59	    .safeParse({
60	    email: formData.get("email"),
61	    password: formData.get("password"),
62	    name: formData.get("name"),
63	  });
64	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
65	  const { email, password, name } = parsed.data;
66	
67	  const existing = await db.user.findUnique({ where: { email } });
68	  if (existing) return { error: "An account with that email already exists." };
69	
70	  // Capture a referral from the `ref` cookie (set by the register page) if the
71	  // code maps to a real user. Self-referral is impossible here (new account).
72	  const jar = await cookies();
73	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
74	  let referredById: string | null = null;
75	  if (refCode) {
76	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
77	    if (referrer) referredById = referrer.id;
78	  }
79	
80	  const referralCode = await uniqueReferralCode();
81	  const user = await db.user.create({
82	    data: {
83	      email,
84	      name,
85	      passwordHash: await bcrypt.hash(password, 12),
86	      referralCode,
87	      referredById,
88	    },
89	  });
90	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
91	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
92	  try {
93	    await grantSignupCredit(user.id);
94	  } catch { /* non-fatal */ }
95	  jar.delete(REF_COOKIE);
96	  try {
97	    const { sendMail, emails } = await import("./mailer");
98	    const tpl = emails.welcome(name);
99	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
100	  } catch { /* email is best-effort */ }
101	  await createSession(user.id);
102	  redirect("/dashboard");
103	}
