160	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
161	async function scheduleNode(planRamMB: number) {
162	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
163	  if (nodes.length === 0) return null;
164	  const loads = await Promise.all(
165	    nodes.map(async (n) => {
166	      const agg = await db.server.findMany({
167	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
168	        select: { plan: { select: { ramMB: true } } },
169	      });
170	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
171	      return { node: n, free: n.capacityRamMB - used };
172	    })
173	  );
174	  loads.sort((a, b) => b.free - a.free);
175	  const best = loads[0];
176	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
177	  return best.node;
178	}
