291	/**
292	 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
293	 * the order (or it's a free admin grant) it provisions immediately; otherwise it
294	 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
295	 * provisions the server on successful payment.
296	 */
297	export async function payAndDeploy(
298	  prev: any,
299	  formData: FormData,
300	): Promise<{ error?: string; checkoutUrl?: string }> {
301	  const user = await requireUser();
302	  const intent = intentFromFormData(formData);
303	
304	  let quote;
305	  try {
306	    quote = await orderQuote(intent);
307	  } catch (e) {
308	    if (e instanceof OrderError) return { error: e.message };
309	    throw e;
310	  }
311	
312	  const isAdmin = user.role === "ADMIN";
313	  const payFromWallet = (intent.free && isAdmin) || user.balanceCents >= quote.chargeCents;
314	
315	  if (payFromWallet) {
316	    let serverId: string;
317	    try {
318	      serverId = await placeOrder(user, intent);
319	    } catch (e) {
320	      if (e instanceof OrderError) return { error: e.message };
321	      throw e;
322	    }
323	    redirect(`/dashboard/servers/${serverId}`);
324	  }
325	
326	  // Pay for the server directly by card; provisioned on payment success.
327	  const url = await createOrderCheckout(user, quote.chargeCents, intent);
328	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
329	  return { checkoutUrl: url };
330	}
