334	async function ownedServer(serverId: string) {
335	  const user = await requireUser();
336	  const server = await db.server.findUnique({ where: { id: serverId } });
337	  if (!server) throw new Error("Not found");
338	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
339	  return { user, server };
340	}
