342	export async function serverAction(serverId: string, action: string) {
343	  const { user, server } = await ownedServer(serverId);
344	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
345	    start: "START",
346	    stop: "STOP",
347	    reboot: "REBOOT",
348	    reinstall: "REINSTALL",
349	    delete: "DELETE",
350	  };
351	  const type = allowed[action];
352	  if (!type) throw new Error("Invalid action");
353	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
354	    throw new Error("Server is suspended");
355	  }
356	
357	  const pending = await db.job.count({
358	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
359	  });
360	  if (pending > 0) return; // debounce: one job at a time per server
361	
362	  if (type === "DELETE") {
363	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
364	  }
365	  await db.job.create({ data: { type, serverId } });
366	  await audit(user.id, `server.${action}`, serverId);
367	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
368	  revalidatePath(`/dashboard/servers/${serverId}`);
369	}
