453	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
454	  const { user, server } = await ownedServer(serverId);
455	  if (server.isFree || !server.expiresAt) return;
456	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
457	  if (!plan) return;
458	  const term = vpsTerm(server.termMonths);
459	  const renewCents =
460	    vpsTermPriceCents(plan.priceCents, term.months) +
461	    (server.wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0);
462	  const owner = await db.user.findUnique({ where: { id: server.userId } });
463	  if (!owner || owner.balanceCents < renewCents) {
464	    return { error: "Insufficient balance — top up your wallet first." };
465	  }
466	
467	  const base = new Date(Math.max(server.expiresAt.getTime(), Date.now()));
468	  try {
469	    await db.$transaction(async (tx) => {
470	      await debitWallet(tx, server.userId, renewCents);
471	      await tx.walletTransaction.create({
472	        data: {
473	          userId: server.userId,
474	          amountCents: -renewCents,
475	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
476	        },
477	      });
478	      await tx.server.update({
479	        where: { id: serverId },
480	        data: { expiresAt: addMonths(base, term.months), suspendedNote: null },
481	      });
482	    });
483	  } catch (e) {
484	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
485	    throw e;
486	  }
487	  await audit(user.id, "server.renew_now", serverId);
488	
489	  // Unpaid-suspended server springs back to life once paid
490	  if (server.status === "SUSPENDED") {
491	    const pending = await db.job.count({
492	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
493	    });
494	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
495	  }
496	  revalidatePath(`/dashboard/servers/${serverId}`);
497	}
