92	// ---------- Admin: coupon management ----------
93	
94	const couponSchema = z.object({
95	  code: z
96	    .string()
97	    .trim()
98	    .min(3)
99	    .max(32)
100	    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
101	  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
102	  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
103	  value: z.coerce.number().int().min(1).max(1_000_000),
104	  firstTimeOnly: z.coerce.boolean(),
105	  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
106	  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
107	  expiresAt: z.string().optional(),
108	  note: z.string().max(200).optional(),
109	});
110	
111	export async function adminCreateCoupon(
112	  prev: any,
113	  formData: FormData
114	): Promise<{ error?: string; ok?: boolean }> {
115	  const admin = await requireAdmin();
116	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
117	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
118	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
119	  const parsed = couponSchema.safeParse({
120	    code: formData.get("code"),
121	    kind: formData.get("kind"),
122	    scope: formData.get("scope"),
123	    value: formData.get("value"),
124	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
125	    minAmountCents: rawMin === "" ? undefined : rawMin,
126	    maxRedemptions: rawMax === "" ? undefined : rawMax,
127	    expiresAt: rawExpires === "" ? undefined : rawExpires,
128	    note: formData.get("note") || undefined,
129	  });
130	  if (!parsed.success) {
131	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
132	  }
133	  const data = parsed.data;
134	  if (data.kind === "PERCENT" && data.value > 100) {
135	    return { error: "Percent value must be between 1 and 100." };
136	  }
137	  const code = data.code.toUpperCase();
