2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "@/lib/db";
5	import { requireArea } from "@/lib/rbac";
6	import { stripe, stripeConfigured } from "@/lib/stripe";
7	
8	/**
9	 * Admin power-tools for finance ops: refunds, manual balance adjustments and
10	 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
11	 * (bulk-suspend is a clients-area capability and gates on "clients") and writes
12	 * an AuditLog row.
13	 *
14	 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`
15	 * and are consumed directly from there (a "use server" file cannot re-export).
16	 */
17	
18	async function audit(userId: string | null, action: string, detail?: string) {
19	  await db.auditLog.create({ data: { userId, action, detail } });
20	}
21	
22	function parseAmountCents(raw: FormDataEntryValue | null): number | null {
23	  const amount = Number(raw);
24	  if (!Number.isFinite(amount) || amount === 0) return null;
25	  if (Math.abs(amount) > 50000) return null; // sanity cap: $50k / action
26	  return Math.round(amount * 100);
27	}
28	
29	/** Pull a Stripe checkout-session id (cs_...) out of a wallet-transaction note. */
30	function sessionIdFrom(description: string | undefined | null): string | null {
31	  const m = (description ?? "").match(/cs_[A-Za-z0-9_]+/);
32	  return m ? m[0] : null;
33	}
34	
35	/**
36	 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
37	 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
38	 * is configured, the money is returned to the original card via the recovered
39	 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
40	 * debits the wallet balance and records the ledger entry.
41	 *
42	 * Safety: the wallet is never driven below zero — for a wallet-only refund we
43	 * require sufficient balance; for a Stripe refund of already-spent funds we
44	 * decrement only what remains (the rest is a real-cash write-off) and note it.
45	 */
46	export async function refundPayment(
47	  _prev: unknown,
48	  formData: FormData
49	): Promise<{ error?: string; message?: string }> {
50	  const admin = await requireArea("billing");
51	
52	  const userId = String(formData.get("userId") ?? "");
53	  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
54	  const cents = parseAmountCents(formData.get("amount"));
55	
56	  if (!userId) return { error: "Missing customer." };
57	  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };
58	
59	  const user = await db.user.findUnique({ where: { id: userId } });
60	  if (!user) return { error: "Customer not found." };
61	
62	  // --- Try to route the refund back to the original Stripe card ---
63	  let method: "stripe" | "wallet" = "wallet";
64	  let stripeRefundId: string | null = null;
65	  if (stripeConfigured()) {
66	    const tx = await db.walletTransaction.findFirst({
67	      where: { userId, description: { contains: "Stripe payment (cs_" } },
68	      orderBy: { createdAt: "desc" },
69	    });
70	    const sessionId = sessionIdFrom(tx?.description);
71	    if (sessionId) {
72	      try {
73	        const session = await stripe().checkout.sessions.retrieve(sessionId);
74	        const pi =
75	          typeof session.payment_intent === "string"
76	            ? session.payment_intent
77	            : session.payment_intent?.id;
78	        if (pi) {
79	          const refund = await stripe().refunds.create({ payment_intent: pi, amount: cents });
80	          stripeRefundId = refund.id;
81	          method = "stripe";
82	        }
83	      } catch {
84	        // Stripe refund failed / not refundable — fall back to wallet-only.
85	        method = "wallet";
86	      }
87	    }
88	  }
89	
90	  const available = Math.max(0, user.balanceCents);
91	  const walletDebit = Math.min(cents, available);
92	  if (method === "wallet" && walletDebit < cents) {
93	    return {
94	      error:
95	        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
96	    };
97	  }
98	
99	  const noteBits = [
100	    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
101	    reason,
102	  ].filter(Boolean);
103	  const description = `Refund — ${noteBits.join(" · ")}`;
104	
105	  await db.$transaction(async (tx) => {
106	    if (walletDebit > 0) {
107	      await tx.user.update({
108	        where: { id: userId },
109	        data: { balanceCents: { decrement: walletDebit } },
110	      });
111	    }
112	    await tx.walletTransaction.create({
113	      data: { userId, amountCents: -cents, description },
114	    });
115	  });
116	
117	  await audit(
118	    admin.id,
119	    "billing.refund",
120	    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
121	      stripeRefundId ? ` (${stripeRefundId})` : ""
122	    }`
123	  );
124	  revalidatePath("/admin/billing");
125	  revalidatePath(`/admin/users/${userId}`);
126	  revalidatePath("/dashboard/billing");
127	
128	  const dollars = `$${(cents / 100).toFixed(2)}`;
129	  return {
130	    message:
131	      method === "stripe"
132	        ? `Refunded ${dollars} to the customer's card (Stripe ${stripeRefundId}).`
133	        : `Refunded ${dollars} to the wallet balance.`,
134	  };
135	}
136	
137	/**
138	 * Manual +/- balance adjustment (credit or debit). A negative amount is the one
139	 * explicit case allowed to drive the balance below zero (e.g. clawing back a
140	 * mistaken credit); positive adjustments simply top the wallet up.
141	 */
142	export async function adjustBalance(
143	  _prev: unknown,
144	  formData: FormData
145	): Promise<{ error?: string; message?: string }> {
146	  const admin = await requireArea("billing");
147	
148	  const userId = String(formData.get("userId") ?? "");
149	  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
150	  const cents = parseAmountCents(formData.get("amount"));
151	
152	  if (!userId) return { error: "Missing customer." };
153	  if (cents === null) return { error: "Enter a non-zero amount (max ±$50,000)." };
154	
155	  const user = await db.user.findUnique({ where: { id: userId } });
156	  if (!user) return { error: "Customer not found." };
157	
158	  const description = `Admin balance adjustment${reason ? ` — ${reason}` : ""}`;
159	  await db.$transaction([
160	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
161	    db.walletTransaction.create({ data: { userId, amountCents: cents, description } }),
162	  ]);
163	
164	  await audit(
165	    admin.id,
166	    "billing.adjust_balance",
167	    `user=${user.email} ${cents >= 0 ? "+" : "−"}$${(Math.abs(cents) / 100).toFixed(2)}`
168	  );
169	  revalidatePath("/admin/billing");
170	  revalidatePath(`/admin/users/${userId}`);
171	  revalidatePath("/dashboard/billing");
172	
173	  const dollars = `$${(Math.abs(cents) / 100).toFixed(2)}`;
174	  return { message: `${cents >= 0 ? "Credited" : "Debited"} ${dollars}. New balance applied.` };
175	}
