177	/**
178	 * Bulk-void a set of open/unpaid invoices. Paid invoices are skipped (they must
179	 * be refunded instead) and already-void ones are ignored. Returns counts.
180	 */
181	export async function bulkVoidInvoices(
182	  ids: string[]
183	): Promise<{ voided: number; skipped: number }> {
184	  const admin = await requireArea("billing");
185	  const unique = [...new Set((ids ?? []).filter(Boolean))].slice(0, 500);
186	  if (unique.length === 0) return { voided: 0, skipped: 0 };
187	
188	  const invoices = await db.invoice.findMany({ where: { id: { in: unique } } });
189	  const voidable = invoices.filter((i) => i.status === "OPEN" || i.status === "REFUNDED");
190	
191	  if (voidable.length > 0) {
192	    await db.invoice.updateMany({
193	      where: { id: { in: voidable.map((i) => i.id) } },
194	      data: { status: "VOID", paidAt: null },
195	    });
196	  }
197	
198	  await audit(admin.id, "billing.bulk_void", `${voidable.length} voided of ${unique.length}`);
199	  revalidatePath("/admin/invoices");
200	  revalidatePath("/dashboard/invoices");
201	  return { voided: voidable.length, skipped: unique.length - voidable.length };
202	}
203	
204	/**
205	 * Bulk-suspend clients. Suspend is a clients-area capability, so this gates on
206	 * "clients" rather than "billing". The acting admin is never suspended.
207	 */
208	export async function bulkSuspendUsers(
209	  ids: string[]
210	): Promise<{ suspended: number }> {
211	  const admin = await requireArea("clients");
212	  const unique = [...new Set((ids ?? []).filter(Boolean))]
213	    .filter((id) => id !== admin.id)
214	    .slice(0, 500);
215	  if (unique.length === 0) return { suspended: 0 };
216	
217	  const res = await db.user.updateMany({
218	    where: { id: { in: unique }, role: { not: "ADMIN" } },
219	    data: { suspended: true },
220	  });
221	
222	  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
223	  revalidatePath("/admin/users");
224	  return { suspended: res.count };
225	}
