1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { requireArea } from "./rbac";
7	import {
8	  computeAffiliateEarnings,
9	  MIN_PAYOUT_CENTS,
10	  PAYOUT_STATUSES,
11	  type PayoutStatus,
12	} from "./affiliate";
13	
14	// ---------- Customer: request a payout ----------
15	
16	/**
17	 * Request an affiliate payout for `amountCents`. Guards:
18	 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
19	 *  - amount ≤ the caller's currently AVAILABLE affiliate balance (earnings minus
20	 *    any non-declined payouts). Availability is recomputed server-side inside the
21	 *    request so a stale client can't over-draw.
22	 * Creates a PENDING AffiliatePayout. Cash-out itself is manual (admin-processed).
23	 */
24	export async function requestAffiliatePayout(
25	  amountCents: number
26	): Promise<{ ok?: boolean; error?: string }> {
27	  const user = await requireUser();
28	
29	  const cents = Math.round(Number(amountCents));
30	  if (!Number.isFinite(cents) || cents <= 0) {
31	    return { error: "Enter a valid amount." };
32	  }
33	  if (cents < MIN_PAYOUT_CENTS) {
34	    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
35	  }
36	
37	  const earnings = await computeAffiliateEarnings(user.id);
38	  if (cents > earnings.availableCents) {
39	    return {
40	      error: `You only have $${(earnings.availableCents / 100).toFixed(2)} available to withdraw.`,
41	    };
42	  }
43	
44	  await db.affiliatePayout.create({
45	    data: { userId: user.id, amountCents: cents, status: "PENDING" },
46	  });
47	  await db.auditLog.create({
48	    data: {
49	      userId: user.id,
50	      action: "affiliate.payout_request",
51	      detail: `$${(cents / 100).toFixed(2)}`,
52	    },
53	  });
54	
55	  revalidatePath("/dashboard/affiliate");
56	  return { ok: true };
57	}
58	
59	// ---------- Admin: update a payout's status ----------
60	
61	const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;
62	
63	/**
64	 * Move a payout request to APPROVED / PAID / DECLINED. On PAID we stamp `paidAt`
65	 * to record the cash-out; other transitions clear it. Billing-area gated.
66	 */
67	export async function adminUpdatePayout(
68	  id: string,
69	  status: string
70	): Promise<{ ok?: boolean; error?: string }> {
71	  const admin = await requireArea("billing");
72	
73	  if (!ALLOWED.includes(status as PayoutStatus)) {
74	    return { error: "Invalid status." };
75	  }
76	  const payout = await db.affiliatePayout.findUnique({ where: { id } });
77	  if (!payout) return { error: "Payout not found." };
78	
79	  await db.affiliatePayout.update({
80	    where: { id },
81	    data: {
82	      status,
83	      paidAt: status === "PAID" ? new Date() : null,
84	    },
85	  });
86	  await db.auditLog.create({
87	    data: {
88	      userId: admin.id,
89	      action: "affiliate.payout_update",
90	      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
91	    },
92	  });
93	
94	  revalidatePath("/admin/affiliate");
95	  return { ok: true };
96	}
