6	
7	/**
8	 * GDPR self-service actions: account deletion and an export summary for the UI.
9	 *
10	 * Everything here is strictly scoped to the *current* signed-in user — a caller
11	 * can only ever act on their own account. No secrets are read or returned.
12	 */
13	
14	/** Servers that still exist for a user (anything not already being torn down). */
15	async function activeServerCount(userId: string): Promise<number> {
16	  return db.server.count({ where: { userId, status: { not: "DELETING" } } });
17	}
18	
19	export type ExportSummary = {
20	  activeServers: number;
21	  walletTransactions: number;
22	  invoices: number;
23	  domains: number;
24	  tickets: number;
25	  sshKeys: number;
26	  memberships: number;
27	};
28	
29	/** Lightweight counts for the "Privacy & data" UI. Own account only. */
30	export async function exportSummary(userId: string): Promise<ExportSummary> {
31	  const user = await requireUser();
32	  if (user.id !== userId) throw new Error("Forbidden");
33	
34	  const [activeServers, walletTransactions, invoices, domains, tickets, sshKeys, memberships] =
35	    await Promise.all([
36	      activeServerCount(user.id),
37	      db.walletTransaction.count({ where: { userId: user.id } }),
38	      db.invoice.count({ where: { userId: user.id } }),
39	      db.domain.count({ where: { userId: user.id } }),
40	      db.ticket.count({ where: { userId: user.id } }),
41	      db.sshKey.count({ where: { userId: user.id } }),
42	      db.membership.count({ where: { userId: user.id } }),
43	    ]);
44	
45	  return { activeServers, walletTransactions, invoices, domains, tickets, sshKeys, memberships };
46	}
47	
48	/**
49	 * Permanently delete the caller's own account.
50	 *
51	 * Guard: the user must type their exact email, and must have NO active server
52	 * (any server with a status other than DELETING). They have to delete their
53	 * servers first — we refuse otherwise so no live VM is orphaned.
54	 *
55	 * The `User` row is removed inside a transaction. Relations that don't cascade
56	 * at the DB level (servers, wallet transactions, audit logs, referrals) are
57	 * cleaned up manually first; the rest cascade from `user.delete`. The deletion
58	 * is audit-logged with `userId: null` before the user disappears.
59	 */
60	export async function deleteMyAccount(confirmEmail: string): Promise<{ error?: string }> {
61	  const user = await requireUser();
62	
63	  const typed = (confirmEmail ?? "").trim().toLowerCase();
64	  if (!typed) return { error: "Type your email to confirm." };
65	  if (typed !== user.email.toLowerCase()) {
66	    return { error: "That email doesn't match your account." };
67	  }
68	
69	  const active = await activeServerCount(user.id);
70	  if (active > 0) {
71	    return {
72	      error: `You still have ${active} active server${active === 1 ? "" : "s"}. Delete ${
73	        active === 1 ? "it" : "them"
74	      } first, then close your account.`,
75	    };
76	  }
77	
78	  await db.$transaction([
79	    // Record the deletion with no owning user (survives the cascade).
80	    db.auditLog.create({
81	      data: {
82	        userId: null,
83	        action: "user.account_deleted",
84	        detail: `${user.email} (${user.id}) — self-service GDPR deletion`,
85	      },
86	    }),
87	    // AuditLog.user has no cascade: anonymize this user's remaining trail.
88	    db.auditLog.updateMany({ where: { userId: user.id }, data: { userId: null } }),
89	    // Self-relation has no cascade: detach anyone this user referred.
90	    db.user.updateMany({ where: { referredById: user.id }, data: { referredById: null } }),
91	    // WalletTransaction.user has no cascade.
92	    db.walletTransaction.deleteMany({ where: { userId: user.id } }),
93	    // Server.user has no cascade. Past the guard only DELETING rows remain;
94	    // removing them cascades jobs, port forwards, dedicated IPs, claude builds, etc.
95	    db.server.deleteMany({ where: { userId: user.id } }),
96	    // PasswordResetToken has no FK relation — hygiene only.
97	    db.passwordResetToken.deleteMany({ where: { userId: user.id } }),
98	    // Cascades: projects, ssh keys, tickets, notifications, domains, invoices,
99	    // api tokens, memberships, owned orgs, coupon redemptions; feedback & gift
100	    // codes are set-null by the schema.
101	    db.user.delete({ where: { id: user.id } }),
102	  ]);
103	
104	  await destroySession();
105	  redirect("/");
106	}
