57	/** Whether the current user has a stored key. Returns a boolean only — never the key. */
58	export async function hasAnthropicKey(): Promise<boolean> {
59	  const user = await requireUser();
60	  const u = await db.user.findUnique({
61	    where: { id: user.id },
62	    select: { anthropicKeyEnc: true },
