97	function esc(s: unknown): string {
98	  return String(s ?? "")
99	    .replace(/&/g, "&amp;")
100	    .replace(/</g, "&lt;")
101	    .replace(/>/g, "&gt;")
102	    .replace(/"/g, "&quot;");
103	}
