7	/**
8	 * Teams / Organizations — shared-account server actions.
9	 *
10	 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
11	 * Every actor is verified to hold a Membership of the required role in the
12	 * target org before any mutation runs, so a hand-crafted request can't touch
13	 * an org the caller doesn't belong to.
14	 *
15	 * SCOPE: this covers org + membership CRUD only. Shared billing (org wallet /
16	 * invoices) and members inheriting access to shared servers are deliberately
17	 * OUT OF SCOPE and left as follow-ups — nothing here changes server ownership.
18	 */
19	
20	const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
21	type OrgRole = (typeof ROLES)[number];
22	
23	function isRole(v: string): v is OrgRole {
24	  return (ROLES as readonly string[]).includes(v);
25	}
26	
27	/** Roles allowed to administer membership (invite / change roles / remove). */
28	function canAdminister(role: string): boolean {
29	  return role === "OWNER" || role === "ADMIN";
30	}
31	
32	/** Load the actor's membership in an org, or null if they aren't a member. */
33	async function actorMembership(orgId: string, userId: string) {
34	  if (!orgId) return null;
35	  return db.membership.findUnique({
36	    where: { orgId_userId: { orgId, userId } },
37	  });
38	}
39	
40	/**
41	 * Create an organization owned by the current user, plus an OWNER membership
42	 * for the creator. Consumed via `useActionState`.
43	 */
44	export async function createOrg(
45	  _prev: unknown,
46	  formData: FormData,
47	): Promise<{ error?: string; ok?: boolean }> {
48	  const user = await requireUser();
49	  const name = String(formData.get("name") ?? "").trim();
50	  if (name.length < 2 || name.length > 60) {
51	    return { error: "Organization name must be 2–60 characters." };
52	  }
53	
54	  await db.organization.create({
55	    data: {
56	      name,
57	      ownerId: user.id,
58	      members: {
59	        create: { userId: user.id, role: "OWNER" },
60	      },
61	    },
62	  });
63	
64	  await db.auditLog.create({
65	    data: { userId: user.id, action: "org.created", detail: name },
66	  });
67	  revalidatePath("/dashboard/team");
68	  return { ok: true };
69	}
70	
71	/**
72	 * Invite a teammate by email. Only OWNER/ADMIN of the org may invite.
73	 * If a user account with that email exists, a Membership is created; otherwise
74	 * a clear message is returned (invitations to non-accounts are a follow-up).
75	 */
76	export async function inviteMember(
77	  orgId: string,
78	  email: string,
79	  role: string,
80	): Promise<{ error?: string; ok?: boolean; message?: string }> {
81	  const user = await requireUser();
82	  const normalizedEmail = String(email ?? "").trim().toLowerCase();
83	  if (!normalizedEmail || !normalizedEmail.includes("@")) {
84	    return { error: "Enter a valid email address." };
85	  }
86	  const wantRole = String(role ?? "MEMBER").toUpperCase();
87	  if (!isRole(wantRole) || wantRole === "OWNER") {
88	    // OWNER is assigned only at creation / ownership transfer, never via invite.
89	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
90	  }
91	
92	  const actor = await actorMembership(orgId, user.id);
93	  if (!actor || !canAdminister(actor.role)) {
94	    return { error: "You don't have permission to invite members to this organization." };
95	  }
96	
97	  const invitee = await db.user.findUnique({ where: { email: normalizedEmail } });
98	  if (!invitee) {
99	    return {
100	      message: `No account with that email yet — ${normalizedEmail} needs to sign up first, then you can add them.`,
101	    };
102	  }
103	
104	  const existing = await actorMembership(orgId, invitee.id);
105	  if (existing) {
106	    return { error: "That person is already a member of this organization." };
107	  }
108	
109	  await db.membership.create({
110	    data: { orgId, userId: invitee.id, role: wantRole },
111	  });
112	  await db.auditLog.create({
113	    data: { userId: user.id, action: "org.member_invited", detail: `${normalizedEmail} → ${wantRole}` },
114	  });
115	  revalidatePath("/dashboard/team");
116	  return { ok: true, message: `${invitee.name} added as ${wantRole.toLowerCase()}.` };
117	}
118	
119	/**
120	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
121	 * pinned to OWNER and cannot be downgraded here.
122	 */
123	export async function updateMemberRole(
124	  orgId: string,
125	  userId: string,
126	  role: string,
127	): Promise<{ error?: string; ok?: boolean }> {
128	  const user = await requireUser();
129	  const wantRole = String(role ?? "").toUpperCase();
130	  if (!isRole(wantRole) || wantRole === "OWNER") {
131	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
132	  }
133	
134	  const actor = await actorMembership(orgId, user.id);
135	  if (!actor || !canAdminister(actor.role)) {
136	    return { error: "You don't have permission to change roles in this organization." };
137	  }
138	
139	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
140	  if (!org) return { error: "Organization not found." };
141	  if (userId === org.ownerId) {
142	    return { error: "The organization owner's role can't be changed." };
143	  }
144	
145	  const target = await actorMembership(orgId, userId);
146	  if (!target) return { error: "That person isn't a member of this organization." };
147	
148	  await db.membership.update({
149	    where: { orgId_userId: { orgId, userId } },
150	    data: { role: wantRole },
151	  });
152	  await db.auditLog.create({
153	    data: { userId: user.id, action: "org.member_role_changed", detail: `${userId} → ${wantRole}` },
154	  });
155	  revalidatePath("/dashboard/team");
156	  return { ok: true };
157	}
158	
159	/**
160	 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
161	 */
162	export async function removeMember(
163	  orgId: string,
164	  userId: string,
165	): Promise<{ error?: string; ok?: boolean }> {
166	  const user = await requireUser();
167	
168	  const actor = await actorMembership(orgId, user.id);
169	  if (!actor || !canAdminister(actor.role)) {
170	    return { error: "You don't have permission to remove members from this organization." };
171	  }
172	
173	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
174	  if (!org) return { error: "Organization not found." };
175	  if (userId === org.ownerId) {
176	    return { error: "The organization owner can't be removed." };
177	  }
178	
179	  await db.membership.deleteMany({ where: { orgId, userId } });
180	  await db.auditLog.create({
181	    data: { userId: user.id, action: "org.member_removed", detail: userId },
182	  });
183	  revalidatePath("/dashboard/team");
184	  return { ok: true };
185	}
186	
187	/**
188	 * Leave an organization. The owner can't leave their own org (they'd have to
189	 * transfer ownership first — a follow-up), everyone else may.
190	 */
191	export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
192	  const user = await requireUser();
193	
194	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
195	  if (!org) return { error: "Organization not found." };
196	  if (org.ownerId === user.id) {
197	    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
198	  }
199	
200	  const membership = await actorMembership(orgId, user.id);
201	  if (!membership) return { error: "You're not a member of this organization." };
202	
203	  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
204	  await db.auditLog.create({
205	    data: { userId: user.id, action: "org.left", detail: orgId },
206	  });
207	  revalidatePath("/dashboard/team");
208	  return { ok: true };
209	}
