93	// ---------- in-process reservations ----------
94	
95	const reservations = new Map<string, number>();
96	
97	function isReserved(key: string): boolean {
98	  const until = reservations.get(key);
99	  if (until === undefined) return false;
100	  if (until <= Date.now()) {
101	    reservations.delete(key);
102	    return false;
103	  }
104	  return true;
105	}
106	
107	function reserve(key: string): void {
108	  if (reservations.size > 5000) {
109	    const now = Date.now();
110	    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
111	  }
112	  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
113	}
114	
115	function isUniqueConflict(e: any): boolean {
116	  return e?.code === "P2002";
117	}
118	
119	type Tx = Prisma.TransactionClient;
120	
121	/**
122	 * Serialise allocators across processes with a transaction-scoped advisory lock
123	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
124	 * transaction — a failing statement inside an open Postgres transaction would
125	 * abort it, so we never speculatively try it in the hot path.
126	 */
127	let advisoryLocks: boolean | null = null;
128	
129	async function lockIpam(tx: Tx): Promise<void> {
130	  if (advisoryLocks === false) return;
131	  await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock($1)", IPAM_LOCK_KEY);
132	}
133	
134	async function probeAdvisoryLocks(): Promise<void> {
135	  if (advisoryLocks !== null) return;
136	  try {
137	    await db.$queryRawUnsafe("SELECT pg_advisory_unlock($1)", IPAM_LOCK_KEY);
138	    advisoryLocks = true;
139	  } catch {
140	    // Not Postgres, or the role lacks permission: the unique-conflict retry
141	    // loop plus in-process reservations remain as the safety net.
142	    advisoryLocks = false;
143	  }
144	}
