146	// ---------- IP allocation ----------
147	
148	/**
149	 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
150	 * same subnet prefix can conflict — servers on other nodes (different prefix)
151	 * are naturally excluded. We still read the column globally because
152	 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
153	 * happens to hold is what keeps the insert from blowing up.
154	 */
155	async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
156	  const rows = await tx.server.findMany({
157	    where: { ipAddress: { startsWith: range.subnetPrefix } },
158	    select: { ipAddress: true },
159	  });
160	  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
161	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
162	    const ip = `${range.subnetPrefix}${i}`;
163	    if (used.has(ip)) continue;
164	    if (isReserved(`ip:${ip}`)) continue;
165	    return ip;
166	  }
167	  throw new Error(
168	    range.nodeId
169	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
170	      : "IP pool exhausted"
171	  );
172	}
173	
174	/**
175	 * Allocate a private IP.
176	 *
177	 * @param nodeId          allocate from this Node's configured subnet/range.
178	 * @param claimForServerId when given, the IP is written onto that Server row in
179	 *                         the same transaction, making the allocation atomic.
180	 */
181	export async function allocateIp(
182	  nodeId?: string | null,
183	  claimForServerId?: string | null
184	): Promise<string> {
185	  const range = await ipamRange(nodeId);
186	  await probeAdvisoryLocks();
187	
188	  if (!claimForServerId) {
189	    // No row to claim against: pick + reserve in-process so concurrent jobs in
190	    // this worker cannot be handed the same address.
191	    const ip = await db.$transaction(async (tx) => {
192	      await lockIpam(tx);
193	      return pickFreeIp(tx, range);
194	    });
195	    reserve(`ip:${ip}`);
196	    return ip;
197	  }
198	
199	  let lastErr: unknown;
200	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
201	    let ip = "";
202	    try {
203	      ip = await db.$transaction(async (tx) => {
204	        await lockIpam(tx);
205	        const candidate = await pickFreeIp(tx, range);
206	        await tx.server.update({
207	          where: { id: claimForServerId },
208	          data: { ipAddress: candidate },
209	        });
210	        return candidate;
211	      });
212	    } catch (e) {
213	      lastErr = e;
214	      if (isUniqueConflict(e)) {
215	        // Someone beat us to it between pick and claim — skip it and retry.
216	        continue;
217	      }
218	      throw e;
219	    }
220	    reserve(`ip:${ip}`);
221	    return ip;
222	  }
223	  throw new Error(
224	    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
225	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
226	  );
227	}
