229	// ---------- SSH forward-port allocation ----------
230	
231	/**
232	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
233	 * taken-set is read globally even though the *range* we scan is per-node.
234	 * Node-awareness therefore comes from the range: give each node a disjoint
235	 * sshPortStart/sshPortEnd window and two nodes can never collide.
236	 */
237	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
238	  const [servers, forwards] = await Promise.all([
239	    tx.server.findMany({
240	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
241	      select: { sshPort: true },
242	    }),
243	    tx.portForward.findMany({
244	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
245	      select: { publicPort: true },
246	    }),
247	  ]);
248	  const used = new Set<number>([
249	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
250	    ...forwards.map((f) => f.publicPort),
251	  ]);
252	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
253	    if (used.has(p)) continue;
254	    if (isReserved(`port:${p}`)) continue;
255	    return p;
256	  }
257	  throw new Error(
258	    range.nodeId
259	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
260	      : "SSH port pool exhausted"
261	  );
262	}
263	
264	/**
265	 * Allocate an SSH forward port.
266	 *
267	 * @param nodeId          allocate from this Node's configured port range.
268	 * @param claimForServerId when given, the port is written onto that Server row
269	 *                         in the same transaction, making it atomic.
270	 */
271	export async function allocateSshPort(
272	  nodeId?: string | null,
273	  claimForServerId?: string | null
274	): Promise<number> {
275	  const range = await ipamRange(nodeId);
276	  await probeAdvisoryLocks();
277	
278	  if (!claimForServerId) {
279	    const port = await db.$transaction(async (tx) => {
280	      await lockIpam(tx);
281	      return pickFreePort(tx, range);
282	    });
283	    reserve(`port:${port}`);
284	    return port;
285	  }
286	
287	  let lastErr: unknown;
288	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
289	    let port = 0;
290	    try {
291	      port = await db.$transaction(async (tx) => {
292	        await lockIpam(tx);
293	        const candidate = await pickFreePort(tx, range);
294	        await tx.server.update({
295	          where: { id: claimForServerId },
296	          data: { sshPort: candidate },
297	        });
298	        return candidate;
299	      });
300	    } catch (e) {
301	      lastErr = e;
302	      if (isUniqueConflict(e)) continue;
303	      throw e;
304	    }
305	    reserve(`port:${port}`);
306	    return port;
307	  }
308	  throw new Error(
309	    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
310	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
311	  );
312	}
