92	/**
93	 * List the vzdump backups on the `backup` storage that belong to this server's
94	 * VMID. Read-only Proxmox call, ownership-checked.
95	 */
96	export async function listServerBackups(
97	  serverId: string
98	): Promise<{ error?: string; backups?: ServerBackup[] }> {
99	  const { server } = await ownedServer(serverId);
100	  if (!server.vmid) return { backups: [] };
101	  try {
102	    const backups = (await listBackups(server.vmid)) as ServerBackup[];
103	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
104	    return { backups };
105	  } catch {
106	    return { error: "Could not reach the hypervisor — try again in a moment." };
107	  }
108	}
