41	function beginSubmit(key: string): boolean {
42	  const now = Date.now();
43	  const heldUntil = inFlightSubmits.get(key);
44	  if (heldUntil !== undefined && heldUntil > now) return false;
45	  if (inFlightSubmits.size > 2000) {
46	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
47	  }
48	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
49	  return true;
50	}
51	
52	function endSubmit(key: string): void {
53	  inFlightSubmits.delete(key);
54	}
