67	/**
68	 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
69	 * (multi-node), and falls back to the env-configured primary when none exist.
70	 */
71	export async function nodeTargets(): Promise<PveTarget[]> {
72	  const nodes = await db.node.findMany({
73	    where: { enabled: true },
74	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
75	  });
76	  if (nodes.length === 0) {
77	    return [
78	      {
