3	/**
4	 * Boot-time validation of critical environment variables.
5	 *
6	 * IMPORTANT: This never throws at import time — a missing var must not break
7	 * the build or crash a server component render. Instead `validateEnv()` returns
8	 * a structured result and logs a single clear warning listing what's missing.
9	 */
10	
11	const envSchema = z.object({
12	  DATABASE_URL: z.string().min(1),
13	  AUTH_SECRET: z.string().min(1),
14	  PROXMOX_API_URL: z.string().min(1),
15	  PROXMOX_NODE: z.string().min(1),
16	  PROXMOX_TOKEN_ID: z.string().min(1),
17	  PROXMOX_TOKEN_SECRET: z.string().min(1),
18	});
19	
20	export type EnvValidation = { ok: boolean; missing: string[] };
21	
22	/**
23	 * Check that all critical env vars are present and non-empty.
24	 * Returns `{ ok, missing[] }` and logs a warning (never throws).
25	 */
26	export function validateEnv(): EnvValidation {
27	  const result = envSchema.safeParse(process.env);
28	  if (result.success) {
29	    return { ok: true, missing: [] };
30	  }
31	  // Collect the top-level keys that failed (missing or empty).
32	  const missing = Array.from(
33	    new Set(result.error.issues.map((i) => String(i.path[0])).filter(Boolean)),
34	  );
35	  console.warn(
36	    `[env] Missing or invalid critical environment variables: ${missing.join(", ")}. ` +
37	      `The app will continue to boot, but features depending on these will fail at runtime.`,
38	  );
39	  return { ok: false, missing };
40	}
